import { describe, expect, it, beforeAll, afterAll } from "vitest";
import { useTemporaryDatabase } from "./server/_support/fixtures";
import { register, login } from "@/server/services/auth-service";
import { resetRateLimits } from "@/lib/rate-limit";
import { toAppError } from "@/lib/errors";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function basePassword() {
  return "Correct-Horse-1";
}

describe("signup edge cases", () => {
  it("reserved-word name", async () => {
    const { org } = await register({
      name: "Admin",
      email: "admin-person@example.com",
      password: basePassword(),
      confirmPassword: basePassword(),
      acceptTerms: true,
    });
    expect(org.slug).not.toBe("admin");
    console.log("reserved-word slug ->", org.slug, org.name);
  });

  it("very short name", async () => {
    const { org } = await register({
      name: "J",
      email: "j-person@example.com",
      password: basePassword(),
      confirmPassword: basePassword(),
      acceptTerms: true,
    });
    expect(org.slug.length).toBeGreaterThanOrEqual(2);
    console.log("short-name slug ->", org.slug, org.name);
  });

  it("no latin letters", async () => {
    const { org } = await register({
      name: "山田",
      email: "yamada-person@example.com",
      password: basePassword(),
      confirmPassword: basePassword(),
      acceptTerms: true,
    });
    console.log("non-latin slug ->", org.slug, org.name);
  });

  it("very long name truncates workspace name but keeps suffix", async () => {
    const longName = "A".repeat(80);
    const { org } = await register({
      name: longName,
      email: "long-name-person@example.com",
      password: basePassword(),
      confirmPassword: basePassword(),
      acceptTerms: true,
    });
    console.log("long name workspace ->", JSON.stringify(org.name), org.name.length);
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
  });

  it("duplicate email, case-insensitive, is a conflict and creates nothing", async () => {
    await register({
      name: "Case Test",
      email: "Case@Example.com",
      password: basePassword(),
      confirmPassword: basePassword(),
      acceptTerms: true,
    });

    await expect(
      register({
        name: "Case Test Two",
        email: "case@example.com",
        password: basePassword(),
        confirmPassword: basePassword(),
        acceptTerms: true,
      }),
    ).rejects.toThrow();

    try {
      await register({
        name: "Case Test Two",
        email: "case@example.com",
        password: basePassword(),
        confirmPassword: basePassword(),
        acceptTerms: true,
      });
    } catch (error) {
      const mapped = toAppError(error);
      console.log("duplicate email ->", mapped.code, mapped.message);
      expect(mapped.code).toBe("conflict");
    }

    // login works with the lowercased spelling
    const { user } = await login({ email: "CASE@EXAMPLE.COM", password: basePassword(), rememberMe: false });
    expect(user.email).toBe("case@example.com");
  });

  it("sign-in throttling maps to rate_limited", async () => {
    resetRateLimits();
    let lastError: unknown = null;
    for (let i = 0; i < 50; i += 1) {
      try {
        await login({ email: "nobody@example.com", password: "wrong-pw-1A", rememberMe: false });
      } catch (error) {
        lastError = error;
      }
    }
    const mapped = toAppError(lastError);
    console.log("throttled sign-in ->", mapped.code, mapped.message);
  });
});

