1	/**
2	 * Credential login, registration and password reset. No third-party provider.
3	 *
4	 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
5	 *
6	 * Note: `TaskflowEventMap` has no authentication event and the type is part of
7	 * the frozen contract, so the declared `emit` is not reachable from here.
8	 * Registration still publishes `member.joined` — through
9	 * `OrganizationService.createOrganization`, which owns that membership row.
10	 */
11	import {
12	  hashPassword,
13	  hashToken,
14	  randomToken,
15	  verifyPassword,
16	} from "@/lib/hash";
17	import { DuplicateEmailError } from "@/lib/errors";
18	import { consumeRateLimit } from "@/lib/rate-limit";
19	import { slugify } from "@/lib/slug";
20	import { ORGANIZATION_NAME_MAX_LENGTH } from "@/schemas/organization";
21	import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
22	import * as sessionRepo from "@/server/repositories/session-repository";
23	import * as userRepo from "@/server/repositories/user-repository";
24	import { toIsoTimestamp } from "@/types/common";
25	import { createOrganization } from "./organization-service";
26	import { renderEmail, sendEmail } from "./email-service";
27	import { createSessionToken } from "./session-service";
28	import type {
29	  LoginInput,
30	  PasswordResetConfirmInput,
31	  PasswordResetRequestInput,
32	  RegisterInput,
33	} from "@/schemas/auth";
34	import type { OrgId, SessionId } from "@/types/common";
35	import type { User } from "@/types/member";
36	import type { Organization } from "@/types/organization";
37	
38	/** Buckets guarding the unauthenticated endpoints. */
39	const LOGIN_BUCKET = "auth:login";
40	const RESET_BUCKET = "auth:password-reset";
41	
42	/**
43	 * Rate limiting before a session exists has no tenant to charge against, so
44	 * every unauthenticated attempt is billed to this sentinel bucket.
45	 */
46	const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;
47	
48	/** How long a password-reset link stays usable. */
49	const RESET_TTL_MS = 60 * 60 * 1000;
50	
51	/** Every workspace this suffix is appended to the owner's display name. */
52	const WORKSPACE_NAME_SUFFIX = "'s workspace";
53	
54	/**
55	 * `<display name>'s workspace`, shortened so the whole thing still fits the
56	 * limit `createOrganizationSchema` enforces on a name — the suffix is never
57	 * dropped, only the display name gives up characters.
58	 */
59	function workspaceNameFor(displayName: string): string {
60	  const full = `${displayName}${WORKSPACE_NAME_SUFFIX}`;
61	  if (full.length <= ORGANIZATION_NAME_MAX_LENGTH) return full;
62	
63	  const maxDisplayLength = ORGANIZATION_NAME_MAX_LENGTH - WORKSPACE_NAME_SUFFIX.length;
64	  return `${displayName.slice(0, maxDisplayLength)}${WORKSPACE_NAME_SUFFIX}`;
65	}
66	
67	/**
68	 * Registration creates the user and their first workspace in one step — a
69	 * Taskflow account with no organization cannot do anything, so there is no
70	 * intermediate state where one exists without the other.
71	 */
72	export async function register(
73	  input: RegisterInput,
74	): Promise<{ user: User; org: Organization }> {
75	  const existing = await userRepo.findUserByEmail(input.email);
76	  if (existing) {
77	    throw new DuplicateEmailError();
78	  }
79	
80	  const user = await userRepo.insertUser({
81	    email: input.email,
82	    name: input.name,
83	    passwordHash: await hashPassword(input.password),
84	  });
85	
86	  // A reserved, too-short or non-Latin name is handled downstream:
87	  // `createOrganization` runs the slug through `uniqueSlug()`, which skips
88	  // reserved words, short results and collisions, and never refuses.
89	  const org = await createOrganization(user.id, {
90	    name: workspaceNameFor(input.name),
91	    slug: slugify(input.name) || "workspace",
92	    plan: "free",
93	  });
94	
95	  const welcome = await renderEmail("welcome", {
96	    orgName: org.name,
97	    recipientName: user.name,
98	  });
99	  await sendEmail({ to: user.email, ...welcome });
100	
101	  return { user, org };
102	}
103	
104	/**
105	 * Credential login. The rate limit is charged before the password is checked,
106	 * so a brute-force run is throttled whether or not it guesses correctly, and
107	 * both failure modes return the same message.
108	 */
109	export async function login(
110	  input: LoginInput,
111	): Promise<{ user: User; token: string }> {
112	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
113	  if (!verdict.allowed) {
114	    throw new Error("Too many sign-in attempts; try again shortly");
115	  }
116	
117	  const user = await userRepo.findUserByEmail(input.email);
118	  if (!user) throw new Error("Those credentials did not match");
119	
120	  const storedHash = await userRepo.findPasswordHash(user.id);
121	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
122	    throw new Error("Those credentials did not match");
123	  }
124	
125	  const { token } = await createSessionToken(user.id);
126	
127	  return { user, token };
128	}
129	
130	export async function logout(sessionId: SessionId): Promise<void> {
131	  await sessionRepo.revokeSession(sessionId);
132	}
133	
134	/**
135	 * Always resolves, whether or not the address is known — telling an anonymous
136	 * caller which emails have accounts is an enumeration oracle. Only the token's
137	 * hash is stored; the raw value exists solely inside the email that carries it.
138	 */
139	export async function requestPasswordReset(
140	  input: PasswordResetRequestInput,
141	): Promise<void> {
142	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
143	  if (!verdict.allowed) return;
144	
145	  const user = await userRepo.findUserByEmail(input.email);
146	  if (!user) return;
147	
148	  const token = randomToken(32);
149	  await resetTokenRepo.issueResetToken(
150	    user.id,
151	    hashToken(token),
152	    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
153	  );
154	
155	  const message = await renderEmail("password-reset", {
156	    recipientName: user.name,
157	    token,
158	    expiresInMinutes: RESET_TTL_MS / 60_000,
159	  });
160	
161	  await sendEmail({ to: user.email, ...message });
162	}
163	
164	/**
165	 * Consumes a reset token and rewrites the password hash. The token is marked
166	 * used before the new hash is written, so a replay of the same link cannot
167	 * overwrite a password the user has since changed again.
168	 */
169	export async function confirmPasswordReset(
170	  input: PasswordResetConfirmInput,
171	): Promise<User> {
172	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
173	  if (!verdict.allowed) {
174	    throw new Error("Too many reset attempts; try again shortly");
175	  }
176	
177	  const stored = await resetTokenRepo.findLiveResetToken(
178	    hashToken(input.token),
179	  );
180	  if (!stored) throw new Error("That reset link is no longer valid");
181	
182	  await resetTokenRepo.consumeResetToken(stored.id);
183	  await userRepo.updatePasswordHash(
184	    stored.userId,
185	    await hashPassword(input.password),
186	  );
187	
188	  const user = await userRepo.findUserById(stored.userId);
189	  if (!user) throw new Error("That reset link is no longer valid");
190	
191	  return user;
192	}
