1	/**
2	 * Maps thrown domain errors onto `AppErrorShape`.
3	 *
4	 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
5	 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
6	 * `ZodError`); Server Actions and Route Handlers never propagate those to the
7	 * client. Everything funnels through `toAppError()` so one thrown class maps
8	 * to exactly one `ErrorCode` and one HTTP status, app-wide.
9	 */
10	import { RateLimitedError } from "@/actions/_lib/action-errors";
11	import { FeatureDisabledError } from "@/lib/feature-flags";
12	import { PermissionDeniedError } from "@/lib/permissions";
13	import { RateLimitExceededError } from "@/lib/rate-limit";
14	import { InvalidSlugError } from "@/lib/slug";
15	import { AlreadyArchivedError } from "@/lib/soft-delete";
16	import { TenantScopeError } from "@/lib/tenant";
17	import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
18	import { ZodError, type ZodIssue } from "zod";
19	
20	/**
21	 * An address that already has an account. Thrown by `AuthService.register` —
22	 * sign-up refuses rather than silently succeeding, per
23	 * `docs/adr/0003-account-creation.md`.
24	 */
25	export class DuplicateEmailError extends Error {
26	  readonly code = "conflict" as const;
27	
28	  constructor() {
29	    super("An account with that email address already exists.");
30	    this.name = "DuplicateEmailError";
31	  }
32	}
33	
34	export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
35	  unauthorized: 401,
36	  forbidden: 403,
37	  not_found: 404,
38	  validation_failed: 422,
39	  conflict: 409,
40	  rate_limited: 429,
41	  plan_limit_exceeded: 402,
42	  tenant_scope_violation: 403,
43	  internal_error: 500,
44	};
45	
46	/** True for the error classes this module knows how to translate faithfully. */
47	export function isDomainError(error: unknown): boolean {
48	  return (
49	    error instanceof PermissionDeniedError ||
50	    error instanceof TenantScopeError ||
51	    error instanceof FeatureDisabledError ||
52	    error instanceof AlreadyArchivedError ||
53	    error instanceof InvalidSlugError ||
54	    error instanceof RateLimitedError ||
55	    error instanceof RateLimitExceededError ||
56	    error instanceof DuplicateEmailError ||
57	    error instanceof ZodError
58	  );
59	}
60	
61	/** Collapses a `ZodError` into the `field → messages` map forms consume. */
62	export function fieldErrorsFromZod(
63	  error: ZodError,
64	): Readonly<Record<string, readonly string[]>> {
65	  const fields: Record<string, string[]> = {};
66	  for (const issue of error.issues as readonly ZodIssue[]) {
67	    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
68	    (fields[key] ??= []).push(issue.message);
69	  }
70	  return fields;
71	}
72	
73	export function toAppError(error: unknown): AppErrorShape {
74	  if (error instanceof ZodError) {
75	    return {
76	      code: "validation_failed",
77	      message: "Please correct the highlighted fields.",
78	      fieldErrors: fieldErrorsFromZod(error),
79	    };
80	  }
81	
82	  if (error instanceof PermissionDeniedError) {
83	    return {
84	      code: "forbidden",
85	      message: error.message,
86	      meta: {
87	        action: error.action,
88	        resourceKind: error.decision.resourceKind,
89	        reason: error.decision.reason,
90	      },
91	    };
92	  }
93	
94	  if (error instanceof TenantScopeError) {
95	    return {
96	      code: "tenant_scope_violation",
97	      message: "That resource belongs to a different organization.",
98	      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
99	    };
100	  }
101	
102	  if (error instanceof FeatureDisabledError) {
103	    return {
104	      code: "forbidden",
105	      message: error.message,
106	      meta: { flag: error.flag },
107	    };
108	  }
109	
110	  if (error instanceof AlreadyArchivedError) {
111	    return {
112	      code: "conflict",
113	      message: error.message,
114	      meta: { entity: error.entity, id: error.id },
115	    };
116	  }
117	
118	  if (error instanceof InvalidSlugError) {
119	    return {
120	      code: "validation_failed",
121	      message: error.message,
122	      fieldErrors: { slug: [error.message] },
123	      meta: { value: error.value },
124	    };
125	  }
126	
127	  if (error instanceof RateLimitedError || error instanceof RateLimitExceededError) {
128	    return {
129	      code: "rate_limited",
130	      message: "Too many attempts. Please wait a moment and try again.",
131	      meta: { bucketKey: error.bucketKey, resetAt: error.resetAt },
132	    };
133	  }
134	
135	  if (error instanceof DuplicateEmailError) {
136	    return {
137	      code: "conflict",
138	      message: error.message,
139	    };
140	  }
141	
142	  return {
143	    code: "internal_error",
144	    message:
145	      error instanceof Error ? error.message : "Something went wrong. Try again.",
146	  };
147	}
148	
149	/** The failure envelope a Server Action returns instead of throwing. */
150	export function toActionResult(error: unknown): ActionResult<never> {
151	  return {
152	    ok: false,
153	    error: toAppError(error),
154	    submittedAt: new Date().toISOString(),
155	  };
156	}
